 10→func TestInstallHooks_FreshInstall(t *testing.T) {
 11→	tempDir := t.TempDir()
 12→	t.Chdir(tempDir)
 13→
 14→	ag := &CursorAgent{}
 15→	count, err := ag.InstallHooks(false, false)
 16→	if err != nil {
 17→		t.Fatalf("InstallHooks() error = %v", err)
 18→	}
 19→
 20→	if count != 6 {
 21→		t.Errorf("InstallHooks() count = %d, want 6", count)
 22→	}
 23→
 24→	hooksFile := readHooksFile(t, tempDir)
 25→
 26→	// Verify all hooks are present
 27→	if len(hooksFile.Hooks.SessionStart) != 1 {
 28→		t.Errorf("SessionStart hooks = %d, want 1", len(hooksFile.Hooks.SessionStart))
 29→	}
 30→	if len(hooksFile.Hooks.SessionEnd) != 1 {
 31→		t.Errorf("SessionEnd hooks = %d, want 1", len(hooksFile.Hooks.SessionEnd))
 32→	}
 33→	if len(hooksFile.Hooks.BeforeSubmitPrompt) != 1 {
 34→		t.Errorf("BeforeSubmitPrompt hooks = %d, want 1", len(hooksFile.Hooks.BeforeSubmitPrompt))
 35→	}
 36→	if len(hooksFile.Hooks.Stop) != 1 {
 37→		t.Errorf("Stop hooks = %d, want 1", len(hooksFile.Hooks.Stop))
 38→	}
 39→	// SubagentStart has 1 (Task)
 40→	if len(hooksFile.Hooks.SubagentStart) != 1 {
 41→		t.Errorf("SubagentStart hooks = %d, want 1", len(hooksFile.Hooks.SubagentStart))
 42→	}
 43→	// SubagentStop has 1 (Task)
 44→	if len(hooksFile.Hooks.SubagentStop) != 1 {
 45→		t.Errorf("SubagentStop hooks = %d, want 1", len(hooksFile.Hooks.SubagentStop))
 46→	}
 47→
 48→	// Verify version
 49→	if hooksFile.Version != 1 {
 50→		t.Errorf("Version = %d, want 1", hooksFile.Version)
 51→	}
 52→
 53→	// Verify commands
 54→	assertEntryCommand(t, hooksFile.Hooks.Stop, "entire hooks cursor stop")
 55→	assertEntryCommand(t, hooksFile.Hooks.SessionStart, "entire hooks cursor session-start")
 56→	assertEntryCommand(t, hooksFile.Hooks.BeforeSubmitPrompt, "entire hooks cursor before-submit-prompt")
 57→
 58→	// Verify matchers on tool hooks
 59→	assertEntryWithMatcher(t, hooksFile.Hooks.SubagentStart, "Subagent", "entire hooks cursor pre-tool")
 60→	assertEntryWithMatcher(t, hooksFile.Hooks.SubagentStop, "Subagent", "entire hooks cursor post-tool")
 61→}
