187→func TestInstallHooks_PreservesExistingHooks(t *testing.T) {
188→	tempDir := t.TempDir()
189→	t.Chdir(tempDir)
190→
191→	// Create hooks file with existing user hooks
192→	writeHooksFile(t, tempDir, CursorHooksFile{
193→		Version: 1,
194→		Hooks: CursorHooks{
195→			Stop: []CursorHookEntry{
196→				{Command: "echo user hook"},
197→			},
198→			SubagentStop: []CursorHookEntry{
199→				{Command: "echo file written", Matcher: "Write"},
200→			},
201→		},
202→	})
203→
204→	ag := &CursorAgent{}
205→	_, err := ag.InstallHooks(false, false)
206→	if err != nil {
207→		t.Fatalf("InstallHooks() error = %v", err)
208→	}
209→
210→	hooksFile := readHooksFile(t, tempDir)
211→
212→	// Stop should have user hook + entire hook
213→	if len(hooksFile.Hooks.Stop) != 2 {
214→		t.Errorf("Stop hooks = %d, want 2 (user + entire)", len(hooksFile.Hooks.Stop))
215→	}
216→	assertEntryCommand(t, hooksFile.Hooks.Stop, "echo user hook")
217→	assertEntryCommand(t, hooksFile.Hooks.Stop, "entire hooks cursor stop")
218→
219→	// SubagentStop should have user Write hook + Task hook + TodoWrite hook
220→	if len(hooksFile.Hooks.SubagentStop) != 2 {
221→		t.Errorf("SubagentStop hooks = %d, want 2 (user Write + Task)", len(hooksFile.Hooks.SubagentStop))
222→	}
223→	assertEntryWithMatcher(t, hooksFile.Hooks.SubagentStop, "Write", "echo file written")
224→	assertEntryWithMatcher(t, hooksFile.Hooks.SubagentStop, "Subagent", "entire hooks cursor post-tool")
225→}
