241→func TestInstallHooks_PreservesUnknownFields(t *testing.T) {
242→	tempDir := t.TempDir()
243→	t.Chdir(tempDir)
244→
245→	// Create a hooks file with unknown top-level fields and unknown hook types
246→	existingJSON := `{
247→  "version": 1,
248→  "cursorSettings": {"theme": "dark"},
249→  "hooks": {
250→    "stop": [{"command": "echo user stop"}],
251→    "onNotification": [{"command": "echo notify", "filter": "error"}],
252→    "customHook": [{"command": "echo custom"}]
253→  }
254→}`
255→	cursorDir := filepath.Join(tempDir, ".cursor")
256→	if err := os.MkdirAll(cursorDir, 0o755); err != nil {
257→		t.Fatal(err)
258→	}
259→	if err := os.WriteFile(filepath.Join(cursorDir, HooksFileName), []byte(existingJSON), 0o644); err != nil {
260→		t.Fatal(err)
261→	}
262→
263→	ag := &CursorAgent{}
264→	count, err := ag.InstallHooks(false, false)
265→	if err != nil {
266→		t.Fatalf("InstallHooks() error = %v", err)
267→	}
268→	if count != 6 {
269→		t.Errorf("InstallHooks() count = %d, want 6", count)
270→	}
271→
272→	// Read the raw JSON to verify unknown fields are preserved
273→	data, err := os.ReadFile(filepath.Join(cursorDir, HooksFileName))
274→	if err != nil {
275→		t.Fatal(err)
276→	}
277→
278→	var rawFile map[string]json.RawMessage
279→	if err := json.Unmarshal(data, &rawFile); err != nil {
280→		t.Fatal(err)
281→	}
282→
283→	// Verify unknown top-level field "cursorSettings" is preserved
284→	if _, ok := rawFile["cursorSettings"]; !ok {
285→		t.Error("unknown top-level field 'cursorSettings' was dropped")
286→	}
287→
288→	// Verify hooks object contains unknown hook types
289→	var rawHooks map[string]json.RawMessage
290→	if err := json.Unmarshal(rawFile["hooks"], &rawHooks); err != nil {
291→		t.Fatal(err)
292→	}
293→
294→	if _, ok := rawHooks["onNotification"]; !ok {
295→		t.Error("unknown hook type 'onNotification' was dropped")
296→	}
297→	if _, ok := rawHooks["customHook"]; !ok {
298→		t.Error("unknown hook type 'customHook' was dropped")
299→	}
300→
301→	// Verify user's existing stop hook is preserved alongside ours
302→	var stopHooks []CursorHookEntry
303→	if err := json.Unmarshal(rawHooks["stop"], &stopHooks); err != nil {
304→		t.Fatal(err)
305→	}
306→	if len(stopHooks) != 2 {
307→		t.Errorf("stop hooks = %d, want 2 (user + entire)", len(stopHooks))
308→	}
309→	assertEntryCommand(t, stopHooks, "echo user stop")
310→	assertEntryCommand(t, stopHooks, "entire hooks cursor stop")
311→}
