 12→func TestParseHookEvent_SessionStart(t *testing.T) {
 13→	t.Parallel()
 14→
 15→	ag := &CursorAgent{}
 16→	input := `{"conversation_id": "test-session-123", "transcript_path": "/tmp/transcript.jsonl"}`
 17→
 18→	event, err := ag.ParseHookEvent(HookNameSessionStart, strings.NewReader(input))
 19→
 20→	if err != nil {
 21→		t.Fatalf("unexpected error: %v", err)
 22→	}
 23→	if event == nil {
 24→		t.Fatal("expected event, got nil")
 25→	}
 26→	if event.Type != agent.SessionStart {
 27→		t.Errorf("expected event type %v, got %v", agent.SessionStart, event.Type)
 28→	}
 29→	if event.SessionID != "test-session-123" {
 30→		t.Errorf("expected session_id 'test-session-123', got %q", event.SessionID)
 31→	}
 32→	if event.SessionRef != "/tmp/transcript.jsonl" {
 33→		t.Errorf("expected session_ref '/tmp/transcript.jsonl', got %q", event.SessionRef)
 34→	}
 35→	if event.Timestamp.IsZero() {
 36→		t.Error("expected non-zero timestamp")
 37→	}
 38→}
