 15→// Ensure CursorAgent implements HookSupport and HookHandler
 16→var (
 17→	_ agent.HookSupport = (*CursorAgent)(nil)
 18→)
 19→
 20→// Cursor hook names - these become subcommands under `entire hooks cursor`
 21→const (
 22→	HookNameSessionStart       = "session-start"
 23→	HookNameSessionEnd         = "session-end"
 24→	HookNameBeforeSubmitPrompt = "before-submit-prompt"
 25→	HookNameStop               = "stop"
 26→	HookNamePreCompact         = "pre-compact"
 27→	HookNameSubagentStart      = "subagent-start"
 28→	HookNameSubagentStop       = "subagent-stop"
 29→)
 30→
 31→// HooksFileName is the hooks file used by Cursor.
 32→const HooksFileName = "hooks.json"
 33→
 34→// entireHookPrefixes are command prefixes that identify Entire hooks
 35→var entireHookPrefixes = []string{
 36→	"entire ",
 37→	"go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go ",
 38→}
 39→
 40→// GetHookNames returns the hook verbs Cursor supports.
 41→// These become subcommands: entire hooks cursor <verb>
 42→func (c *CursorAgent) GetHookNames() []string {
 43→	return []string{
 44→		HookNameSessionStart,
 45→		HookNameSessionEnd,
 46→		HookNameBeforeSubmitPrompt,
 47→		HookNameStop,
 48→		HookNamePreCompact,
 49→		HookNameSubagentStart,
 50→		HookNameSubagentStop,
 51→	}
 52→}
 53→
 54→// InstallHooks installs Cursor hooks in .cursor/hooks.json.
 55→// If force is true, removes existing Entire hooks before installing.
 56→// Returns the number of hooks installed.
 57→// Unknown top-level fields and hook types are preserved on round-trip.
 58→func (c *CursorAgent) InstallHooks(localDev bool, force bool) (int, error) {
 59→	repoRoot, err := paths.RepoRoot()
 60→	if err != nil {
 61→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when RepoRoot() fails (tests run outside git repos)
 62→		if err != nil {
 63→			return 0, fmt.Errorf("failed to get current directory: %w", err)
 64→		}
 65→	}
 66→
 67→	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
 68→
 69→	// Use raw maps to preserve unknown fields on round-trip
 70→	var rawFile map[string]json.RawMessage
 71→	var rawHooks map[string]json.RawMessage
 72→
 73→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 74→	if readErr == nil {
 75→		if err := json.Unmarshal(existingData, &rawFile); err != nil {
 76→			return 0, fmt.Errorf("failed to parse existing "+HooksFileName+": %w", err)
 77→		}
 78→		if hooksRaw, ok := rawFile["hooks"]; ok {
 79→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 80→				return 0, fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
 81→			}
 82→		}
 83→		if _, ok := rawFile["version"]; !ok {
 84→			rawFile["version"] = json.RawMessage(`1`)
 85→		}
 86→	} else {
 87→		rawFile = map[string]json.RawMessage{
 88→			"version": json.RawMessage(`1`),
 89→		}
 90→	}
 91→
 92→	if rawHooks == nil {
 93→		rawHooks = make(map[string]json.RawMessage)
 94→	}
 95→
 96→	// Parse only the hook types we manage
 97→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
 98→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
 99→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
100→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
101→	parseCursorHookType(rawHooks, "stop", &stop)
102→	parseCursorHookType(rawHooks, "preCompact", &preCompact)
103→	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
104→	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
105→
106→	// If force is true, remove all existing Entire hooks first
107→	if force {
108→		sessionStart = removeEntireHooks(sessionStart)
109→		sessionEnd = removeEntireHooks(sessionEnd)
110→		beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
111→		stop = removeEntireHooks(stop)
112→		preCompact = removeEntireHooks(preCompact)
113→		subagentStart = removeEntireHooks(subagentStart)
114→		subagentStop = removeEntireHooks(subagentStop)
115→	}
116→
117→	// Define hook commands
118→	var cmdPrefix string
119→	if localDev {
120→		cmdPrefix = "go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go hooks cursor "
121→	} else {
122→		cmdPrefix = "entire hooks cursor "
123→	}
124→
125→	sessionStartCmd := cmdPrefix + "session-start"
126→	sessionEndCmd := cmdPrefix + "session-end"
127→	beforeSubmitPromptCmd := cmdPrefix + "before-submit-prompt"
128→	stopCmd := cmdPrefix + HookNameStop
129→	preCompactCmd := cmdPrefix + HookNamePreCompact
130→	subagentStartCmd := cmdPrefix + HookNameSubagentStart
131→	subagentEndCmd := cmdPrefix + HookNameSubagentStop
132→
133→	count := 0
134→
135→	// Add hooks if they don't exist
136→	if !hookCommandExists(sessionStart, sessionStartCmd) {
137→		sessionStart = append(sessionStart, CursorHookEntry{Command: sessionStartCmd})
138→		count++
139→	}
140→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
141→		sessionEnd = append(sessionEnd, CursorHookEntry{Command: sessionEndCmd})
142→		count++
143→	}
144→	if !hookCommandExists(beforeSubmitPrompt, beforeSubmitPromptCmd) {
145→		beforeSubmitPrompt = append(beforeSubmitPrompt, CursorHookEntry{Command: beforeSubmitPromptCmd})
146→		count++
147→	}
148→	if !hookCommandExists(stop, stopCmd) {
149→		stop = append(stop, CursorHookEntry{Command: stopCmd})
150→		count++
151→	}
152→	if !hookCommandExists(preCompact, preCompactCmd) {
153→		preCompact = append(preCompact, CursorHookEntry{Command: preCompactCmd})
154→		count++
155→	}
156→	if !hookCommandExists(subagentStart, subagentStartCmd) {
157→		subagentStart = append(subagentStart, CursorHookEntry{Command: subagentStartCmd})
158→		count++
159→	}
160→	if !hookCommandExists(subagentStop, subagentEndCmd) {
161→		subagentStop = append(subagentStop, CursorHookEntry{Command: subagentEndCmd})
162→		count++
163→	}
164→
165→	if count == 0 {
166→		return 0, nil
167→	}
168→
169→	// Marshal modified hook types back into rawHooks
170→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
171→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
172→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
173→	marshalCursorHookType(rawHooks, "stop", stop)
174→	marshalCursorHookType(rawHooks, "preCompact", preCompact)
175→	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
176→	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
177→
178→	// Marshal hooks and update raw file
179→	hooksJSON, err := json.Marshal(rawHooks)
180→	if err != nil {
181→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
182→	}
183→	rawFile["hooks"] = hooksJSON
184→
185→	// Write to file
186→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
187→		return 0, fmt.Errorf("failed to create .cursor directory: %w", err)
188→	}
189→
190→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
191→	if err != nil {
192→		return 0, fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
193→	}
194→
195→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
196→		return 0, fmt.Errorf("failed to write "+HooksFileName+": %w", err)
197→	}
198→
199→	return count, nil
200→}
