319→// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
320→// Silently ignores parse errors (leaves target unchanged).
321→func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
322→	if data, ok := rawHooks[hookType]; ok {
323→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
324→		json.Unmarshal(data, target)
325→	}
326→}
327→
328→// marshalCursorHookType marshals a hook type back into rawHooks.
329→// If the slice is empty, removes the key from rawHooks.
330→func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
331→	if len(entries) == 0 {
332→		delete(rawHooks, hookType)
333→		return
334→	}
335→	data, err := json.Marshal(entries)
336→	if err != nil {
