342→// Helper functions for hook management
343→
344→func hookCommandExists(entries []CursorHookEntry, command string) bool {
345→	for _, entry := range entries {
346→		if entry.Command == command {
347→			return true
348→		}
349→	}
350→	return false
351→}
352→
353→func isEntireHook(command string) bool {
354→	for _, prefix := range entireHookPrefixes {
355→		if strings.HasPrefix(command, prefix) {
356→			return true
357→		}
358→	}
359→	return false
360→}
361→
362→func hasEntireHook(entries []CursorHookEntry) bool {
363→	for _, entry := range entries {
364→		if isEntireHook(entry.Command) {
365→			return true
366→		}
367→	}
368→	return false
369→}
370→
371→func removeEntireHooks(entries []CursorHookEntry) []CursorHookEntry {
372→	result := make([]CursorHookEntry, 0, len(entries))
