 18→// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
 19→// Returns nil if the hook has no lifecycle significance.
 20→func (c *CursorAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
 21→	switch hookName {
 22→	case HookNameSessionStart:
 23→		return c.parseSessionStart(stdin)
 24→	case HookNameBeforeSubmitPrompt:
 25→		return c.parseTurnStart(stdin)
 26→	case HookNameStop:
 27→		return c.parseTurnEnd(stdin)
 28→	case HookNameSessionEnd:
