 30→	case HookNamePreCompact:
 31→		return c.parsePreCompact(stdin)
 32→	case HookNameSubagentStart:
 33→		return c.parseSubagentStart(stdin)
 34→	case HookNameSubagentStop:
 35→		return c.parseSubagentStop(stdin)
 36→	default:
 37→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 38→	}
 39→}
